def _dependencies(data, preference, name_order):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    roots = data["roots"]
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    best_vector = None
    best_versions = None

    choices = [[None] + rows for rows in (packages[name] for name in names)]
    for selection in product(*choices):
        rows = {name: row for name, row in zip(names, selection) if row is not None}
        versions = {name: row["version"] for name, row in rows.items()}

        if any(name not in versions or not bounds[0] <= versions[name] <= bounds[1]
               for name, bounds in roots.items()):
            continue
        if any(name in versions and versions[name] != version
               for name, version in pins.items()):
            continue
        if any(version in blocked.get(name, []) for name, version in versions.items()):
            continue

        graph = {name: [] for name in rows}
        valid = True
        for name, row in rows.items():
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                other = dep["name"]
                version = versions.get(other)
                if version is None or not dep["min"] <= version <= dep["max"]:
                    valid = False
                    break
                graph[name].append(other)
            if not valid:
                break
        if not valid:
            continue

        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            stack.extend(graph[name])
        if reachable != set(rows):
            continue

        state = {}
        def visit(name):
            if state.get(name) == 1:
                return False
            if state.get(name) == 2:
                return True
            state[name] = 1
            if any(not visit(other) for other in graph[name]):
                return False
            state[name] = 2
            return True

        if not all(visit(name) for name in rows):
            continue

        ordered = names if name_order == "ascending" else list(reversed(names))
        vector = tuple(versions.get(name, -1) for name in ordered)
        if (best_vector is None or
                (vector < best_vector if preference == "minimum" else vector > best_vector)):
            best_vector = vector
            best_versions = versions

    return {"versions": best_versions} if best_versions is not None else {"error": "unsatisfiable"}


def _ledger(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for position, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (sequence, event.get("revision", 0), position)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]

    def rounded(n):
        if mode == "floor":
            return n // 10000
        return (n + 5000) // 10000

    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount))
        tax = rounded(raw * event.get("tax_bp", 0))
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _quota_intervals(data):
    jobs = [job for job in data["jobs"]
            if job["id"] not in data.get("blocked", [])]
    k = data["k"]
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None

    for subset in combinations(jobs, k):
        ids = tuple(sorted(job["id"] for job in subset))
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(subset, key=lambda job: (job["start"], job["end"]))
        if any(ordered[i - 1]["end"] > ordered[i]["start"]
               for i in range(1, len(ordered))):
            continue
        value = sum(job["value"] for job in subset)
        if (best_value is None or value > best_value or
                (value == best_value and ids > best_ids)):
            best_value, best_ids = value, ids

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def _temporal_routes(data):
    import heapq

    required = data.get("required", [])
    full_mask = (1 << len(required)) - 1
    node_bits = {}
    for i, node in enumerate(required):
        node_bits[node] = node_bits.get(node, 0) | (1 << i)
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    start = data["source"]
    mask = node_bits.get(start, 0)
    remaining = data["coupons"]
    initial = (start, mask, remaining)
    distances = {initial: data["start"]}
    queue = [(data["start"], start, mask, remaining)]

    while queue:
        arrival, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distances.get(state) != arrival:
            continue
        if (node == data["target"] and mask == full_mask and remaining == 0):
            return {"arrival": arrival}

        for edge in graph[node]:
            depart = max(arrival, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], remaining)]
            if remaining:
                options.append((max(1, edge["duration"] - edge.get("discount", 0)), remaining - 1))
            next_mask = mask | node_bits.get(edge["v"], 0)
            for duration, next_remaining in options:
                next_arrival = depart + duration
                if next_arrival > data["deadline"]:
                    continue
                next_state = (edge["v"], next_mask, next_remaining)
                if next_arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = next_arrival
                    heapq.heappush(queue, (next_arrival, edge["v"], next_mask, next_remaining))
    return {"arrival": None}


